import{_ as a,C as d,o as e,c as p,a3 as n,E as i}from"./chunks/framework.D4-ViStF.js";const m=JSON.parse('{"title":"断占总诀篇之四：占卜十应诀","description":"从正应到人事应，整理全书收束的十个观察维度。","frontmatter":{"title":"断占总诀篇之四：占卜十应诀","description":"从正应到人事应，整理全书收束的十个观察维度。","category":"学习计划 · 第三阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/duan-zhan-zong-jue/ten-omens-formula.md","filePath":"yijing/meihua-yishu/duan-zhan-zong-jue/ten-omens-formula.md","lastUpdated":1787738987000}'),l={name:"yijing/meihua-yishu/duan-zhan-zong-jue/ten-omens-formula.md"};function r(o,t,g,c,h,b){const s=d("DaoTextReading");return e(),p("div",null,[t[0]||(t[0]=n("",5)),i(s,{colophon:"占卜十应诀 · 论事十大应 · 卦应",tone:"ink",sections:[{id:"sec-01",label:"占卜十应诀",showLabel:!0,sentences:[["凡占卜，以体卦为主，用为事应，固然矣。"],["但体卦既为主，用互卦相应，参看祸福。"],["然今日得此一卦，体用互变中决之如此；明日复得此卦，体用一般，岂可又复以此决之？"],["然则若何而可？"],["必得",{text:"十应",glossary:"g01"},"之说而后可也。"],["盖",{text:"十应",glossary:"g01"},"之说，有正应、互应、变应、日应、",{text:"刻应",glossary:"g03"},"、外应、天时应、地理应、人事应、所谓",{text:"十应",glossary:"g01"},"也。"]]},{id:"sec-01-1",label:"",showLabel:!0,sentences:[["夫正应者，正卦之应也。"],["互应者，互卦之应也。"],["变应者，变卦之应也。"],["此二卦之诀也。"],["占者俱用之以断吉凶矣。"],["至于诸应之理，人有不知者，故必得诸用之诀，卦无不验。"],["不得其诀而占卜吉凶，或验或不验矣。"],["得此诀者，宜秘之。"]]},{id:"sec-01-2",label:"",showLabel:!0,sentences:[["正应：正应者，即体用二卦决吉凶。"],["互应：互应者，即互卦中决吉凶。"],["变应：变应者，即变卦中决吉凶。"],["方应：方应者，以体为主，看来占之人在何方位上，即看其所坐立之方位。"],["宜生体卦，又宜与体比和，则吉；如克体卦则凶，如体卦生之，亦不吉矣。"]]},{id:"sec-01-3",label:"",showLabel:!0,sentences:[["日应：日应者，以体卦为主，看所占属何卦，及体卦与本日衰旺如何。"],["盖卦宜生体，宜比和；不宜克体，亦不宜体卦生之也。"],["本日所属卦气如寅卯木、巳午火、申酉金、亥子水、辰戌丑未土也。"]]},{id:"sec-01-4",label:"",showLabel:!0,sentences:[["刻应：刻应者，即三要之诀也。"],["占卜之顷，随所闻所见吉凶之兆以为吉凶之应。"],["外应：外应者，外卦之应也。"],["占卜之际，偶见外物之来者，即看其物属何卦。"],["如火得离、水得坎之类。"],["如见老人、马、金玉圆物，得干。"],["见老妇、牛、土瓦物，得坤之类。"],["又如见此者，为外应之卦。"],["并看其卦与体卦生克比和之理，以决吉凶。"]]},{id:"sec-01-5",label:"",showLabel:!0,sentences:[["天时应：天时之应，占卜之际，晴明为离，雨雪为坎，风为巽，雷为震。"],["如离为体，宜晴。"],["坎为体，宜雨。"],["巽为体，宜风。"],["震为体，宜雷。"],["火见雷为比和，参之生克，以定吉凶。"]]},{id:"sec-01-6",label:"",showLabel:!0,sentences:[["地理应：地理之应，占卜之时，在竹林间，为震、巽之地；在江河溪涧池沼之上为坎；在五金之处为干、兑之乡；在窑灶炉火之所为离；在土瓦之所为坤、艮，并为体卦，论生克比和之理以诀之。"],["人事应：人事之应，即三要中人事之克应也。"],["盖占卜之际，偶遇人事之吉为吉，偶遇人事之凶为凶。"],["如闻笑语，主有吉庆之事；遇哭泣，主有悲愁之事，又以人事之属于卦者论之：老人为干，老妇为坤，少男为艮，少女为兑。"],["并看此人事之卦与体卦生克比和，以决吉凶。"]]},{id:"sec-01-7",label:"",showLabel:!0,sentences:[["此",{text:"十应",glossary:"g01"},"之理，凡占卜之际，耳闻目见以决吉凶，并以体卦为主，而详见生克比和之理。"],["如占病症，互变中俱有克体之卦，而本卦中又无生体之卦者，断不吉也。"],["又看体衰旺，若体旺则庶几有望，体衰则无复生理。"],["如是，又看诸应有生体者，险中有救；有克体则不可望安矣。"],["其余占卜，并以类推之。"]]},{id:"sec-02",label:"论事十大应（论日辰秘文）",showLabel:!0,sentences:[["一行：问官事，属木，旺木有文书；属火，有官司；财金，财有至。"],["有客至问病，人火潮热，金水米浆。"]]},{id:"sec-02-1",label:"",showLabel:!0,sentences:[["二立：官司不发，木土无金，大小口舌，病不凶。"],["财水土，有贵人至，文书发动。"]]},{id:"sec-02-2",label:"",showLabel:!0,sentences:[["三坐：问官司，有讼不成。"],["主财属火，主和劝。"],["金败财，木得财。"],["病却月，又有犯林木神，有祸不凶。"]]},{id:"sec-02-3",label:"",showLabel:!0,sentences:[["四卧：问官司侧睡者，欲起必作，主阴人事。"],["金有财，火事发破财。"],["土水无财难就。"],["土木有财。"]]},{id:"sec-02-4",label:"",showLabel:!0,sentences:[["五",{text:"担",glossary:"g07"},"：官司被人自惊，与面说人成口舌。"],["问信见水土得财。"],["金木客至。"],["病有犯，四肢沉重不能起。"]]},{id:"sec-02-5",label:"",showLabel:!0,sentences:[["六",{text:"券",glossary:"g06"},"：官司不成，火有财，水土有灾。"],["心下不安，有贵人，主口舌，不凶。"]]},{id:"sec-02-6",label:"",showLabel:!0,sentences:[["七",{text:"裹头",glossary:"g05"},"：官司立见口舌。"],["火，大官司；水土比和。"],["财无，小人分上。"],["口舌呕气。"],["病主阴人小口灾。"]]},{id:"sec-02-7",label:"",showLabel:!0,sentences:[["八",{text:"跣足",glossary:"g04"},"：官司破财，外人欺，心下惊慌。"],["火主破财，土不凶。"],["病有孝至。"]]},{id:"sec-02-8",label:"",showLabel:!0,sentences:[["九喜：官司自己无主，外人有请，劝官司。"],["有酒肉，别人事。"],["口舌纷纷，求财不许。"],["不凶。"]]},{id:"sec-02-9",label:"",showLabel:!0,sentences:[["十怒：官司主外人欺凌，不见官，主破财。"],["倚人脱卸，火惊病凶。"]]},{id:"sec-03",label:"卦应",showLabel:!0,sentences:[["乾：为天、为圆、为君、为父、为首、为金、为玉、为寒、为冰、为大赤、为良马、为老马、为",{text:"瘠马",glossary:"g37"},"、为",{text:"驳马",glossary:"g38"},"、为木果。"]]},{id:"sec-03-1",label:"",showLabel:!0,sentences:[["《九家易》云：为龙、为直、为衣、为言。"],["如姤、遁、否、履、无妄、讼、同人七卦，干在上，刚在外。"],["如大有、泰、大壮、夬、需、大畜、小畜七卦，干在下，刚于内。"],["乾坤刚柔，四发变八，惟六动随时有异，不拘于一。"],["干性温而刚直，位西北，不居子午而居戌亥。"],["附于礼王，则为刚善，为明；不附于礼法，则为刚恶，为凶暴。"]]},{id:"sec-03-2",label:"",showLabel:!0,sentences:[["天文：雪、老阳；"],["天气：寒；"],["凶盗：军弓手、贼、强横、",{text:"停尸",glossary:"g39"},"官贵：朝贵、盐司、大守、",{text:"座主",glossary:"g40"},"身体：顶、面颊、",{text:"頄辅",glossary:"g08"},"性情：刚健正直、尊重、好高、战吉；声音：正、清、商；信音：朝信改、召命、荐举、关升、义亲； 事意：上卦为形象之家，下卦为强横之辈； 疾病：太阳脉弦紧，天威所罚、",{text:"上壅",glossary:"g09"},{text:"目熟",glossary:"g10"},"、寒热+ 附药：丸子坤：为地、为母、为布、为釜、为",{text:"吝啬",glossary:"g11"},"、为均、为子母牛、为",{text:"大舆",glossary:"g12"},"、为文、为众、为柄、其于地也为黑。"],["震：为雷、为龙、为玄黄、为",{text:"旉",glossary:"g13"},"、为",{text:"大涂",glossary:"g14"},"、为长子、为",{text:"决躁",glossary:"g15"},"、为",{text:"苍筤竹",glossary:"g16"},"、为",{text:"萑苇",glossary:"g17"},"、其于马也为善鸣、为",{text:"馵足",glossary:"g18"},"、为作足、为",{text:"的颡",glossary:"g19"},"、其于稼也为",{text:"反生",glossary:"g20"},"、其究为健、为",{text:"蕃鲜",glossary:"g21"},"。"],["巽：为木、为风、为长女、为绳直、为工、为白、为长、为高、为进退、为不果、为臭、其于人也为",{text:"寡发",glossary:"g22"},"、为",{text:"广颡",glossary:"g23"},"、为多白眼、为",{text:"近利市三位",glossary:"g24"},"、其究为躁卦。"],["坎：为水、为",{text:"沟渎",glossary:"g25"},"、为隐伏、为",{text:"矫輮",glossary:"g26"},"、为弓轮、其于人也为加忧、为心病、为耳痛、为血卦、为赤、其于马也为美脊、为",{text:"亟心",glossary:"g27"},"、为下首、为薄蹄、为曳、其于舆也为",{text:"多眚",glossary:"g28"},"、为通、为月、为盗、其于木也为坚多心。"],["离：为火、为日、为电、为中女、为",{text:"甲胄",glossary:"g29"},"、为戈兵、其于人也为大腹、为干卦、为鳖、为蟹、为",{text:"蠃",glossary:"g30"},"、为蚌、为龟、其于木也为",{text:"科上槁",glossary:"g31"},"。"],["艮：为山、为径路、为小石、为门阙、为",{text:"果蓏",glossary:"g32"},"、为",{text:"阍寺",glossary:"g33"},"、为指、为狗、为鼠、为",{text:"黔喙",glossary:"g34"},"之属、其于木也为坚多节。"],["兑：为泽、为少女、为巫、为口舌、为毁折、为",{text:"附决",glossary:"g36"},"、其于地也为",{text:"刚卤",glossary:"g35"},"、为妾、为羊。"]]}],glossary:[{id:"g01",term:"十应",pinyin:"shí yìng",meaning:"十种感应方式，断卦的十个维度"},{id:"g02",term:"方应",pinyin:"fāng yìng",meaning:"来占者所在方位的感应"},{id:"g03",term:"刻应",pinyin:"kè yìng",meaning:"占卜当刻所见所闻的感应（即三要）"},{id:"g04",term:"跣足",pinyin:"xiǎn zú",meaning:"赤脚，不穿鞋"},{id:"g05",term:"裹头",pinyin:"guǒ tóu",meaning:"以布裹头，古代丧服或病态之象"},{id:"g06",term:"券",pinyin:"quàn",meaning:"契约·券书，此处指持券之人"},{id:"g07",term:"担",pinyin:"dān",meaning:"挑担，肩挑重物"},{id:"g08",term:"頄辅",pinyin:"qiú fǔ",meaning:"颧骨与辅骨，面颊两侧骨骼"},{id:"g09",term:"上壅",pinyin:"yōng",meaning:"上部壅塞，头面部气血壅滞"},{id:"g10",term:"目熟",pinyin:"—",meaning:"眼目昏熟，视物不清"},{id:"g11",term:"吝啬",pinyin:"lìn sè",meaning:"坤为吝啬，收敛·不轻易给予"},{id:"g12",term:"大舆",pinyin:"yú",meaning:"大车，坤为大车·承载"},{id:"g13",term:"旉",pinyin:"fū",meaning:"敷布·展开，震为旉：雷声展布四方"},{id:"g14",term:"大涂",pinyin:"tú",meaning:"大道·宽广道路"},{id:"g15",term:"决躁",pinyin:"—",meaning:"果决急躁，震之性情"},{id:"g16",term:"苍筤竹",pinyin:"láng",meaning:"青嫩之竹，筤：竹初生之色"},{id:"g17",term:"萑苇",pinyin:"huán wěi",meaning:"芦苇类植物"},{id:"g18",term:"馵足",pinyin:"zhù",meaning:"后左足白色之马，馵：马后足白"},{id:"g19",term:"的颡",pinyin:"sǎng",meaning:"额头有白斑之马，的：白色斑点"},{id:"g20",term:"反生",pinyin:"—",meaning:"根向上生，倒生之稼（震为反生）"},{id:"g21",term:"蕃鲜",pinyin:"fān xiān",meaning:"茂盛鲜嫩"},{id:"g22",term:"寡发",pinyin:"—",meaning:"头发稀少，巽之人象"},{id:"g23",term:"广颡",pinyin:"sǎng",meaning:"宽额头"},{id:"g24",term:"近利市三位",pinyin:"—",meaning:"善于经商逐利，三位：多方位"},{id:"g25",term:"沟渎",pinyin:"dú",meaning:"沟渠·水道"},{id:"g26",term:"矫輮",pinyin:"jiǎo róu",meaning:"矫正弯曲，坎为矫輮：水能使物弯曲或矫直"},{id:"g27",term:"亟心",pinyin:"jí",meaning:"急躁之心，坎马为亟心：性急"},{id:"g28",term:"多眚",pinyin:"shěng",meaning:"多灾多难，眚：灾祸"},{id:"g29",term:"甲胄",pinyin:"zhòu",meaning:"盔甲，甲：铠甲，胄：头盔"},{id:"g30",term:"蠃",pinyin:"luǒ",meaning:"螺类，有壳之软体动物"},{id:"g31",term:"科上槁",pinyin:"kē gǎo",meaning:"树干上部枯槁，离火炎上故上部枯"},{id:"g32",term:"果蓏",pinyin:"luǒ",meaning:"果蓏：木本之果为果，草本之果为蓏"},{id:"g33",term:"阍寺",pinyin:"hūn sì",meaning:"守门之人，阍：守门者；寺：侍者"},{id:"g34",term:"黔喙",pinyin:"qián huì",meaning:"黑嘴之兽，黔：黑色，喙：嘴"},{id:"g35",term:"刚卤",pinyin:"lǔ",meaning:"坚硬盐碱之地，兑为刚卤"},{id:"g36",term:"附决",pinyin:"—",meaning:"附着而决裂，兑之性：附而后断"},{id:"g37",term:"瘠马",pinyin:"jí",meaning:"瘦弱之马"},{id:"g38",term:"驳马",pinyin:"bó",meaning:"毛色杂乱之马"},{id:"g39",term:"停尸",pinyin:"—",meaning:"乾为凶盗中有停尸：主死亡停棺之象"},{id:"g40",term:"座主",pinyin:"—",meaning:"科举主考官，乾为官贵之座主"}],"aria-label":"占卜十应诀原文"}),t[1]||(t[1]=n("",118))])}const y=a(l,[["render",r]]);export{m as __pageData,y as default};
